class GateLayerNormGRU(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, num_layers: int,
                 batch_first: bool = True, dropout: float = 0.0):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.batch_first = batch_first
        self.cells = nn.ModuleList([
            nn.GRUCell(input_size if layer == 0 else hidden_size, hidden_size)
            for layer in range(num_layers)
        ])
        self.gate_norms = nn.ModuleList([
            nn.ModuleList([nn.LayerNorm(hidden_size) for _ in range(3)])
            for _ in range(num_layers)
        ])
        self.interlayer_dropout = nn.Dropout(dropout)

    def forward(self, inputs: torch.Tensor, hx: torch.Tensor | None = None):
        x = inputs if self.batch_first else inputs.transpose(0, 1)
        if hx is None:
            hx = x.new_zeros(self.num_layers, x.size(0), self.hidden_size)
        final_states = []
        for layer, (cell, norms) in enumerate(zip(self.cells, self.gate_norms)):
            projected = torch.nn.functional.linear(x, cell.weight_ih, cell.bias_ih)
            hidden = hx[layer]
            states = []
            for input_gates in projected.unbind(dim=1):
                hidden_gates = torch.nn.functional.linear(
                    hidden, cell.weight_hh, cell.bias_hh
                )
                input_r, input_z, input_n = input_gates.chunk(3, dim=-1)
                hidden_r, hidden_z, hidden_n = hidden_gates.chunk(3, dim=-1)
                reset = torch.sigmoid(norms[0](input_r + hidden_r))
                update = torch.sigmoid(norms[1](input_z + hidden_z))
                candidate = torch.tanh(norms[2](input_n + reset * hidden_n))
                hidden = (1.0 - update) * candidate + update * hidden
                states.append(hidden)
            x = torch.stack(states, dim=1)
            final_states.append(hidden)
            if layer + 1 < self.num_layers:
                x = self.interlayer_dropout(x)
        output = x if self.batch_first else x.transpose(0, 1)
        return output, torch.stack(final_states, dim=0)


